using SchoolERP.Application.Features.Subjects;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Exceptions;using Xunit;namespace SchoolERP.UnitTests;public sealed class SubjectManagementTests{[Fact]public void Request_does_not_accept_tenant_or_school(){var p=typeof(CreateSubjectRequest).GetProperties().Select(x=>x.Name);Assert.DoesNotContain("TenantId",p);Assert.DoesNotContain("SchoolId",p);}[Fact]public void Subject_create_sets_ownership_draft_and_normalizes(){var t=Guid.NewGuid();var s=Guid.NewGuid();var y=Guid.NewGuid();var x=Subject.Create(t,s,y," Mathematics "," math_01 ",SubjectType.Core,2,credits:3.5m,periods:5);Assert.Equal((t,s,y),(x.TenantId,x.SchoolId,x.AcademicYearId));Assert.Equal("MATH_01",x.Code);Assert.Equal(SubjectStatus.Draft,x.Status);Assert.Equal(3.5m,x.CreditHours);Assert.Equal(5,x.WeeklyPeriods);Assert.False(x.IsElective);}[Theory][InlineData("A B")][InlineData("A@B")][InlineData("")]public void Invalid_code_rejected(string c)=>Assert.Throws<DomainException>(()=>Subject.NormalizeCode(c));[Theory][InlineData("0")][InlineData("-1")][InlineData("100.01")]public void Invalid_credit_rejected(string value)=>Assert.Throws<DomainException>(()=>Subject.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"X","X",SubjectType.Core,0,credits:decimal.Parse(value)));[Theory][InlineData(0)][InlineData(-1)][InlineData(51)]public void Invalid_periods_rejected(int p)=>Assert.Throws<DomainException>(()=>Subject.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"X","X",SubjectType.Core,0,periods:p));[Fact]public void Class_subject_preserves_hierarchy_and_order(){var t=Guid.NewGuid();var s=Guid.NewGuid();var y=Guid.NewGuid();var c=Guid.NewGuid();var subject=Guid.NewGuid();var x=ClassSubject.Create(t,s,y,c,subject,true,3);Assert.Equal((t,s,y,c,subject),(x.TenantId,x.SchoolId,x.AcademicYearId,x.SchoolClassId,x.SubjectId));Assert.True(x.IsMandatory);Assert.Equal(3,x.DisplayOrder);}[Fact]public void Archived_subject_is_read_only(){var x=Subject.Create(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"X","X",SubjectType.Core,0);x.Archive(DateTime.UtcNow);Assert.Throws<DomainException>(()=>x.UpdateDetails("Y",null,SubjectType.Core,null,0,null,null,null,DateTime.UtcNow));}}
